if(k==='quarrel'){setRel(S,a,b,-0.15,'険悪');a.m.sus=clamp(a.m.sus+5,0,100);b.m.sus=clamp(b.m.sus+5,0,100);why='疑心暗鬼が、二人の仲をこじらせた';}
