if(!ps.length||rng()>0.2)return false;
var pr=rng.pick(ps),a= !FD.lhFrom(S,pr[1],pr[0])?pr[0]:pr[0].tr.aggr+pr[0].tr.cp>=pr[1].tr.aggr+pr[1].tr.cp?pr[0]:pr[1],b=a===pr[0]?pr[1]:pr[0];
a.lhDay=b.lhDay=day;
